const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

if (body.entityType !== 'company') {
  throw new Error('intel-030-account-knowledge requiert entityType="company"');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    callbackUrl: body.callbackUrl,
  }
}];

const upstream = $('Validate Entity').item.json;
const context = $input.first().json;

// ADR-0012 D-3 — le LLM ne peut émettre que 3 des 5 valeurs de provenance :
// - 'relational'   : fait dérivé du relationnel KREDO (contacts/opportunités/missions/signaux)
//                     OU du diagnostic process (artefact déjà produit par le moteur KREDO,
//                     pas un import brut — le fit imparfait avec 'engine_researched'
//                     [pensé pour de la recherche web datée] est un choix documenté ici,
//                     pas un oubli : processDiagnostic est plus fiable qu'un simple 'inferred').
// - 'folio_legacy'  : fait dérivé de companies.metadata.analysis_data (import FOLIO, sans source).
// - 'inferred'      : déduction du LLM non traçable à une entrée précise.
// 'human_verified' (réservé à la curation manager) et 'engine_researched' (réservé aux futurs
// workflows de recherche web datée) sont REJETÉS s'ils apparaissent en sortie — cf. Parse & Validate.

const SYSTEM_PROMPT = `Tu rédiges la "Connaissance compte" pour Kredo Digital (ESN premium : Data/IA,
Cloud, Product Management, Cybersécurité) — étape 1 de la chaîne de décision commerciale
(ADR-0012). Ce n'est PAS une étude marché ni une recommandation d'offre : uniquement ce
que l'on sait factuellement du compte lui-même.

RÈGLES ABSOLUES :
1. Le CONTEXTE ci-dessous (JSON) est ta SEULE source. N'invente aucun fait, aucun chiffre,
   aucun nom qui n'y figure explicitement.
2. Chaque fait produit doit porter une provenance parmi EXACTEMENT ces 3 valeurs :
   - "relational" : dérivé de context.contacts / context.opportunities / context.missions /
     context.recentInteractions / context.signals (relationnel KREDO direct) OU de context.processDiagnostic s'il est présent.
   - "folio_legacy" : dérivé de context.folioAnalysisData (import FOLIO, à traiter comme peu fiable
     et daté — jamais présenté comme une vérité certaine).
   - "inferred" : déduction que tu formules toi-même sans qu'elle soit directement traçable.
   N'utilise JAMAIS "human_verified" ni "engine_researched" — ces valeurs sont réservées.
3. Exclus tout ce qui relève du secteur/marché macro (context ne t'en donne pas — normal),
   de la recommandation d'offre, ou d'une roadmap d'actions : ce sont d'autres étapes de la chaîne.
4. Si une section n'a rien de solide à dire, renvoie un tableau vide plutôt que d'inventer.
5. Style direct, factuel, sans superlatifs creux.

FORMAT DE SORTIE — JSON valide UNIQUEMENT, sans backticks, structure EXACTE :
{
  "schema_version": 1,
  "identity_positioning": [ { "text": "...", "provenance": "relational|folio_legacy|inferred" } ],
  "commercial_relationship": [ { "text": "...", "provenance": "..." } ],
  "key_contacts": [ { "role_summary": "..." } ],
  "organisation_observed": [ { "text": "...", "provenance": "..." } ],
  "frictions_and_signals": [ { "text": "...", "provenance": "..." } ],
  "open_questions": [ { "text": "...", "provenance": "inferred" } ]
}
Note : open_questions est TOUJOURS "inferred" par nature (ce sont des hypothèses à valider,
pas des faits établis). key_contacts n'a pas de provenance (dérivé mécaniquement des contacts).`;

const userPrompt = `CONTEXTE (source unique de vérité — JSON) :\n${JSON.stringify(context, null, 2)}`;

return [{
  json: {
    ...upstream,
    context,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

