const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (parsed.schema_version !== 1) {
  throw new Error('schema_version doit valoir 1');
}

const SECTIONS = ['identity_positioning', 'commercial_relationship', 'organisation_observed', 'frictions_and_signals', 'open_questions'];
const ALLOWED_PROVENANCE = new Set(['relational', 'folio_legacy', 'inferred']);

for (const section of SECTIONS) {
  if (!Array.isArray(parsed[section])) {
    throw new Error(`Section manquante ou invalide : ${section}`);
  }
  for (const fact of parsed[section]) {
    if (!fact.text || typeof fact.text !== 'string') {
      throw new Error(`Fait sans texte dans ${section}`);
    }
    if (!ALLOWED_PROVENANCE.has(fact.provenance)) {
      throw new Error(`Provenance non autorisée dans ${section} : "${fact.provenance}" (autorisé: relational, folio_legacy, inferred)`);
    }
  }
}

if (!Array.isArray(parsed.key_contacts)) {
  throw new Error('key_contacts manquant ou invalide');
}
for (const kc of parsed.key_contacts) {
  if (!kc.role_summary || typeof kc.role_summary !== 'string') {
    throw new Error('key_contacts : role_summary manquant');
  }
}

const accountKnowledge = {
  schema_version: 1,
  identity_positioning: parsed.identity_positioning,
  commercial_relationship: parsed.commercial_relationship,
  key_contacts: parsed.key_contacts,
  organisation_observed: parsed.organisation_observed,
  frictions_and_signals: parsed.frictions_and_signals,
  open_questions: parsed.open_questions,
  generated_at: new Date().toISOString(),
};

return [{
  json: {
    ...upstream,
    accountKnowledge,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

// Contrôles qualité — heuristiques simples (pas de NLP), un flag n'est jamais
// un blocage dur, juste une donnée exposée dans qaFlags côté UI (cf. ADR-0009/INTEL-020).
const data = $input.first().json;
const ak = data.accountKnowledge;
const qaFlags = [];

const totalFacts = ['identity_positioning', 'commercial_relationship', 'organisation_observed', 'frictions_and_signals', 'open_questions']
  .reduce((sum, s) => sum + ak[s].length, 0);
qaFlags.push({ check: 'has_facts', passed: totalFacts > 0, detail: `${totalFacts} faits au total` });

const hasContacts = (data.context.contacts || []).length > 0;
qaFlags.push({
  check: 'key_contacts_present_if_contacts_exist',
  passed: !hasContacts || ak.key_contacts.length > 0,
  detail: hasContacts ? `${ak.key_contacts.length} synthèses pour ${data.context.contacts.length} contacts` : 'aucun contact en base',
});

const openQuestionsAllInferred = ak.open_questions.every((f) => f.provenance === 'inferred');
qaFlags.push({
  check: 'open_questions_are_inferred',
  passed: openQuestionsAllInferred,
  detail: openQuestionsAllInferred ? 'OK' : 'des hypothèses ne sont pas taguées inferred',
});

const hasFolioInput = !!(data.context.folioAnalysisData && Object.keys(data.context.folioAnalysisData).length > 0);
const usesFolio = ['identity_positioning', 'commercial_relationship', 'organisation_observed', 'frictions_and_signals']
  .some((s) => ak[s].some((f) => f.provenance === 'folio_legacy'));
qaFlags.push({
  check: 'folio_provenance_consistent',
  passed: usesFolio ? hasFolioInput : true,
  detail: usesFolio && !hasFolioInput ? 'facts tagged folio_legacy mais aucune donnée FOLIO en entrée' : 'OK',
});

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;
const companyName = (data.context.company && data.context.company.name) || 'Compte';

const sourceRefs = [
  { entityType: 'company', entityId: data.companyId, label: 'Fiche compte' },
];

const callbackBody = {
  runId: data.runId,
  phase: 1,
  resultType: 'account_knowledge',
  status: 'succeeded',
  contentJson: data.accountKnowledge,
  contentText: [
    `# Connaissance compte — ${companyName}`,
    ...data.accountKnowledge.identity_positioning.map((f) => f.text),
    ...data.accountKnowledge.commercial_relationship.map((f) => f.text),
  ].join('\n\n'),
  title: `Connaissance compte — ${companyName}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.context,
  sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const ve = $('Validate Entity').item.json;
  runId = ve.runId || null;
  callbackUrl = ve.callbackUrl || null;
} catch (e) {
  // Validate Entity n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow intel-030-account-knowledge';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 1,
  resultType: 'account_knowledge',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
